"""Prints the keynote folders and items of the project as an indented tree, using GetKeynoteTree.

Requires Archicad 28 or later.
"""
import aclib

def PrintFolder (folder, indent):
    print ('  ' * indent + '[{}] {}'.format (folder['key'], folder['title']))
    for item in folder['items']:
        print ('  ' * (indent + 1) + '{} {}'.format (item['key'], item['title']))
    for subFolder in folder['subFolders']:
        PrintFolder (subFolder, indent + 1)

tree = aclib.RunTapirCommand ('GetKeynoteTree')
for folder in tree['foldersInRoot']:
    PrintFolder (folder, 0)
for item in tree['itemsInRoot']:
    print ('{} {}'.format (item['key'], item['title']))

"""Creates a keynote folder with a keynote item in it, using CreateKeynoteItems.

Deletes the folder and the item at the end. Requires Archicad 28 or later.
"""
import aclib

folder = aclib.RunTapirCommand ('CreateKeynoteFolders', {
    'foldersData': [{'key': 'TAPIR', 'title': 'Tapir Example Folder'}]
})['keynoteFolderIdsOrErrors'][0]

aclib.PrintJson (aclib.RunTapirCommand ('CreateKeynoteItems', {
    'itemsData': [{
        'parentFolderId': folder['keynoteFolderId'],
        'key': 'TAPIR-01',
        'title': 'Tapir Example Keynote',
        'description': 'Created by the Tapir example.',
        'reference': 'EX-1'
    }]
}))

aclib.RunTapirCommand ('DeleteKeynoteFolders', {'keynoteFolderIds': [{'keynoteFolderId': folder['keynoteFolderId']}]})

"""Creates a keynote folder and changes its title with ModifyKeynoteFolders.

Deletes the folder at the end. Requires Archicad 28 or later.
"""
import aclib

folder = aclib.RunTapirCommand ('CreateKeynoteFolders', {
    'foldersData': [{'key': 'TAPIR', 'title': 'Tapir Example Folder'}]
})['keynoteFolderIdsOrErrors'][0]

aclib.PrintJson (aclib.RunTapirCommand ('ModifyKeynoteFolders', {
    'foldersData': [{'keynoteFolderId': folder['keynoteFolderId'], 'title': 'Tapir Renamed Folder'}]
}))

aclib.RunTapirCommand ('DeleteKeynoteFolders', {'keynoteFolderIds': [{'keynoteFolderId': folder['keynoteFolderId']}]})

"""Creates a keynote item and changes its title and description with ModifyKeynoteItems.

